CREATE TABLE IF NOT EXISTS public.portfolio_projects (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE,
 title text NOT NULL, description text NOT NULL, image text NOT NULL,
 category text NOT NULL, technologies jsonb NOT NULL DEFAULT '[]',
 project_url text NOT NULL DEFAULT '', github_url text NOT NULL DEFAULT '',
 featured boolean NOT NULL DEFAULT false, display_order integer NOT NULL DEFAULT 0,
 surfaces jsonb NOT NULL, metadata jsonb NOT NULL DEFAULT '{}',
 updated_at timestamptz NOT NULL DEFAULT now(),
 CHECK (length(title) BETWEEN 1 AND 200), CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$')
);
ALTER TABLE public.portfolio_projects ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.portfolio_projects FROM PUBLIC, anon, authenticated;
GRANT ALL ON public.portfolio_projects TO service_role;
